import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('roundCents rounds half to even (0.5)', () => {
  assert.equal(roundCents(124.5), 124);
  assert.equal(roundCents(125.5), 126);
});

test('roundCents ignores binary noise', () => {
  assert.equal(roundCents(2.4), 2);
  assert.equal(roundCents(-0.5), 0);
});

test('formatEuros adds the sign, thousands separators and two decimals', () => {
  assert.equal(formatEuros(123456), '€1,234.56');
  assert.equal(formatEuros(-5), '-€0.05');
  assert.equal(formatEuros(0), '€0.00');
  assert.equal(formatEuros(1000000), '€10,000.00');
});

test('parseEuros reads what people type', () => {
  assert.equal(parseEuros('12').value, 1200);
  assert.equal(parseEuros('12.5').value, 1250);
  assert.equal(parseEuros('1,234.56').value, 123456);
});

test('RATES object has correct values', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR to USD', () => {
  const result = convert(10000, 'USD');

  assert.equal(result.ok, true);
  assert.equal(result.value, 10850);
});

test('convert EUR to GBP', () => {
  const result = convert(10000, 'GBP');

  assert.equal(result.ok, true);
  assert.equal(result.value, 8425);
});

test('convert EUR to EUR', () => {
  const result = convert(10000, 'EUR');

  assert.equal(result.ok, true);
  assert.equal(result.value, 10000);
});

test('convert rejects unknown currency', () => {
  const result = convert(10000, 'JPY');

  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_CURRENCY' });
});

test('convert rounds result to whole cents', () => {
  const result = convert(100, 'GBP');

  assert.equal(result.ok, true);
  assert.equal(result.value, 84);
});

test('convert handles zero amount', () => {
  const result = convert(0, 'USD');

  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('convert handles negative amounts', () => {
  const result = convert(-10000, 'USD');

  assert.equal(result.ok, true);
  assert.equal(result.value, -10850);
});

test('convert large amounts', () => {
  const result = convert(1000000, 'USD');

  assert.equal(result.ok, true);
  assert.equal(result.value, 1085000);
});

test('formatMoney EUR', () => {
  const result = formatMoney(123456, 'EUR');

  assert.equal(result, '€1,234.56');
});

test('formatMoney USD', () => {
  const result = formatMoney(123456, 'USD');

  assert.equal(result, '$1,234.56');
});

test('formatMoney GBP', () => {
  const result = formatMoney(123456, 'GBP');

  assert.equal(result, '£1,234.56');
});

test('formatMoney USD negative', () => {
  const result = formatMoney(-123456, 'USD');

  assert.equal(result, '-$1,234.56');
});

test('formatMoney GBP negative', () => {
  const result = formatMoney(-123456, 'GBP');

  assert.equal(result, '-£1,234.56');
});

test('formatMoney zero amount', () => {
  assert.equal(formatMoney(0, 'USD'), '$0.00');
  assert.equal(formatMoney(0, 'GBP'), '£0.00');
  assert.equal(formatMoney(0, 'EUR'), '€0.00');
});

test('formatMoney small amount', () => {
  assert.equal(formatMoney(5, 'USD'), '$0.05');
  assert.equal(formatMoney(100, 'GBP'), '£1.00');
});

test('formatMoney large amount with thousands', () => {
  assert.equal(formatMoney(1000000, 'USD'), '$10,000.00');
  assert.equal(formatMoney(12345678, 'GBP'), '£123,456.78');
});

test('formatMoney unknown currency falls back to EUR', () => {
  const result = formatMoney(123456, 'JPY');

  assert.equal(result, '€1,234.56');
});

test('convert and formatMoney together for USD', () => {
  const converted = convert(10000, 'USD');
  const formatted = formatMoney(converted.value, 'USD');

  assert.equal(formatted, '$108.50');
});

test('convert and formatMoney together for GBP', () => {
  const converted = convert(10000, 'GBP');
  const formatted = formatMoney(converted.value, 'GBP');

  assert.equal(formatted, '£84.25');
});

test('formatMoney has exactly 2 decimal places', () => {
  const amounts = [
    formatMoney(100, 'USD'),
    formatMoney(1000, 'GBP'),
    formatMoney(123456, 'EUR'),
  ];

  amounts.forEach((formatted) => {
    const parts = formatted.split('.');
    assert.equal(parts.length, 2);
  });
});

test('formatMoney includes currency symbol', () => {
  assert.ok(formatMoney(10000, 'USD').includes('$'));
  assert.ok(formatMoney(10000, 'GBP').includes('£'));
  assert.ok(formatMoney(10000, 'EUR').includes('€'));
});

test('convert multiple USD amounts', () => {
  const amounts = [100, 1000, 10000, 100000];
  const converted = amounts.map((amt) => convert(amt, 'USD').value);

  converted.forEach((amt, idx) => {
    assert.equal(amt, roundCents(amounts[idx] * 1.085));
  });
});

test('convert multiple GBP amounts', () => {
  const amounts = [100, 1000, 10000, 100000];
  const converted = amounts.map((amt) => convert(amt, 'GBP').value);

  converted.forEach((amt, idx) => {
    assert.equal(amt, roundCents(amounts[idx] * 0.8425));
  });
});

